    function ucwords(str) {
        return (str || '').replace(/-/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); });
    }

    function extractLocationFromDOM() {
        if (typeof document === 'undefined') return null;

        // 1. Try body / button data-location
        const dataLocEl = document.querySelector('[data-location], [data-geo-location]');
        if (dataLocEl) {
            const val = dataLocEl.getAttribute('data-location') || dataLocEl.getAttribute('data-geo-location');
            if (val && val.trim()) return val.trim();
        }

        // 2. Try H1 / hero title for "in [Location]" pattern
        const h1 = document.querySelector('h1, .hero-title, .local-h1');
        if (h1) {
            const txt = h1.innerText || h1.textContent || '';
            const m = txt.match(/\bin\s+([A-Za-z0-9\s,–—-]+?)(?:\s*[|–—-]|$)/i);
            if (m && m[1]) {
                const locCandidate = m[1].trim().replace(/[\s,]+$/, '');
                if (locCandidate.length > 2 && !locCandidate.toLowerCase().includes('best') && !locCandidate.toLowerCase().includes('top')) {
                    return locCandidate;
                }
            }
        }

        // 3. Try meta geo tags
        const metaGeo = document.querySelector('meta[name="geo.placename"]');
        const metaRegion = document.querySelector('meta[name="geo.region"]');
        if (metaGeo && metaGeo.content) {
            let place = metaGeo.content.trim();
            if (metaRegion && metaRegion.content) {
                const r = metaRegion.content.toUpperCase();
                const regMap = {'IN-TG':'Telangana','IN-AP':'Andhra Pradesh','IN-TN':'Tamil Nadu','IN-KA':'Karnataka','IN-KL':'Kerala','IN-MH':'Maharashtra','IN-RJ':'Rajasthan','IN-DL':'Delhi','IN-GJ':'Gujarat','IN-UP':'Uttar Pradesh','IN-WB':'West Bengal'};
                if (regMap[r] && !place.includes(regMap[r])) {
                    place += ', ' + regMap[r];
                }
            }
            return place;
        }

        return null;
    }

    function resolveSmartGeoLocation(input, fallback) {
        // First check if DOM has the exact location
        const domLoc = extractLocationFromDOM();
        if (domLoc && domLoc.includes(',')) {
            return domLoc;
        }

        if (!input) return domLoc || fallback || 'India';
        let clean = (input + '').trim().toLowerCase();

        if (clean.includes('?')) clean = clean.split('?')[0];
        if (clean.includes('#')) clean = clean.split('#')[0];
        clean = clean.replace(/^https?:\/\/[^\/]+/i, '');
        clean = clean.replace(/^\/+|\/+$/g, '');
        if (clean.includes('/')) {
            const segs = clean.split('/');
            let found = false;
            for (let i = segs.length - 1; i >= 0; i--) {
                if (segs[i].includes('-in-') || segs[i].startsWith('in-')) {
                    clean = segs[i];
                    found = true;
                    break;
                }
            }
            if (!found) clean = segs[segs.length - 1];
        }

        // Extract location after '-in-' if present in URL/slug
        if (clean.includes('-in-')) {
            clean = clean.replace(/^.*?-in-/i, '');
        }

        clean = clean.replace(/^(?:in-|near-|at-|service-in-|nets-in-|safety-nets-in-|dealers-in-|cost-in-|price-in-)/i, '');
        clean = clean.replace(/(?:-dealers|-near-me|-installation|-services|-price|-cost|-wholesalers|-manufacturers|-rate)$/i, '');
        clean = clean.trim();

        if (!clean) return domLoc || fallback || 'India';

        if (/(telangana|andhra pradesh|karnataka|tamil nadu|maharashtra|kerala|delhi|gujarat|rajasthan|uttar pradesh|west bengal|madhya pradesh|odisha|bihar|jharkhand|chhattisgarh|assam|punjab|haryana|uttarakhand|himachal pradesh|goa|jammu)/i.test(clean) && clean.includes(',')) {
            return clean.split(',').map(s => ucwords(s.trim())).join(', ');
        }

        const cleanBase = clean.replace(/-/g, ' ');

        if (masterGeo[clean]) return masterGeo[clean];
        if (masterGeo[cleanBase]) return masterGeo[cleanBase];

        const stripped = clean.replace(/-(?:dt|district|dist|area|mandal|town|city|tehsil|taluk|village|hub|zone|colony|layout|road|street|junction|x-roads|cross-roads|crossroads)$/i, '');
        const strippedBase = stripped.replace(/-/g, ' ');
        if (masterGeo[stripped]) return masterGeo[stripped];
        if (masterGeo[strippedBase]) return masterGeo[strippedBase];

        if (domLoc) return domLoc;
        if (fallback) return fallback;
        return ucwords(cleanBase);
    }

    if (typeof module !== 'undefined' && module.exports) {
        module.exports = resolveSmartGeoLocation;
    }
    root.resolveSmartGeoLocation = resolveSmartGeoLocation;
    root.extractLocationFromDOM = extractLocationFromDOM;
